create or replace function public.recalcular_premio_ciclo(p_ciclo uuid) returns numeric language plpgsql security invoker set search_path=public as $$ declare v numeric; begin select coalesce(sum(c.valor_cota),0) * (1-coalesce(ci.percentual_administracao,0)/100) into v from ciclos ci left join jogos j on j.ciclo_id=ci.id and j.pagamento_status='CONFIRMADO' left join concursos c on c.id=j.concurso_id where ci.id=p_ciclo group by ci.percentual_administracao; update ciclos set premio_acumulado=coalesce(v,0) where id=p_ciclo; return coalesce(v,0); end $$;
create or replace function public.trg_recalcular_premio() returns trigger language plpgsql security invoker set search_path=public as $$ begin perform public.recalcular_premio_ciclo(coalesce(new.ciclo_id,old.ciclo_id)); return coalesce(new,old); end $$;
drop trigger if exists jogos_recalcular_premio on public.jogos;create trigger jogos_recalcular_premio after insert or update of pagamento_status on public.jogos for each row execute function public.trg_recalcular_premio();
create index if not exists apuracoes_concurso_idx on public.apuracoes(concurso_id);create index if not exists apuracoes_acertos_idx on public.apuracoes(acertos_acumulados desc);create index if not exists ganhadores_ciclo_idx on public.ganhadores(ciclo_id);
